LEVELS = ["UNCLASSIFIED", "CONFIDENTIAL", "SECRET", "TOP_SECRET"]


def rank(level):
    return LEVELS.index(level)


def bell_lapadula(subject_level, object_level, operation):
    s, o = rank(subject_level), rank(object_level)
    if operation == "read":
        return o <= s
    if operation == "write":
        return o >= s
    raise ValueError(operation)


def biba(subject_level, object_level, operation):
    s, o = rank(subject_level), rank(object_level)
    if operation == "read":
        return o >= s
    if operation == "write":
        return o <= s
    raise ValueError(operation)


checks = [
    ("SECRET", "TOP_SECRET", "read"),
    ("SECRET", "UNCLASSIFIED", "write"),
    ("SECRET", "SECRET", "read"),
]

for subject, obj, op in checks:
    bl = "ALLOW" if bell_lapadula(subject, obj, op) else "DENY"
    bi = "ALLOW" if biba(subject, obj, op) else "DENY"
    print(f"{op} {subject}->{obj}: Bell-LaPadula={bl} Biba={bi}")
